package de.fh_aachen.android.testing

import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.test.advanceUntilIdle
import kotlinx.coroutines.test.runTest
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Rule
import org.junit.Test

/*
 * A fake: a small, working implementation of the interface, made for tests. It answers
 * immediately and records what it was asked to do. (A mock, e.g. with MockK or Mockito, is
 * generated by a library and checks calls; fakes are simpler and often enough.)
 * This only works because TallyViewModel gets its repository through the constructor -
 * with a global lookup (ServiceLocator, Application.instance) there would be no way in.
 */
class FakeTallyRepository(private var stored: Int = 0) : TallyRepository {
    val saved = mutableListOf<Int>()
    override suspend fun load(): Int = stored
    override suspend fun save(count: Int) { saved += count; stored = count }
}

/*
 * 2. Local unit tests of a ViewModel: the coroutines run on the test dispatcher (MainDispatcherRule),
 *    runTest gives us a coroutine for the test body, and advanceUntilIdle() runs everything that
 *    is waiting. The pattern of every test: Arrange (set up), Act (do something), Assert (check).
 */
@OptIn(ExperimentalCoroutinesApi::class)
class TallyViewModelTest {

    @get:Rule
    val mainDispatcherRule = MainDispatcherRule()

    @Test
    fun loadsTheStoredCount() = runTest {
        val viewModel = TallyViewModel(FakeTallyRepository(stored = 7))
        assertTrue(viewModel.state.value.isLoading)     // the loading coroutine has not run yet

        advanceUntilIdle()

        assertEquals(7, viewModel.state.value.tally.count)
        assertFalse(viewModel.state.value.isLoading)
    }

    @Test
    fun everyChangeOfTheCountIsSaved() = runTest {
        val repository = FakeTallyRepository()
        val viewModel = TallyViewModel(repository)
        advanceUntilIdle()

        viewModel.onAction(TallyAction.Increment)
        viewModel.onAction(TallyAction.Increment)
        viewModel.onAction(TallyAction.Decrement)
        advanceUntilIdle()

        assertEquals(1, viewModel.state.value.tally.count)
        assertEquals(listOf(1, 2, 1), repository.saved)
    }

    @Test
    fun changingTheStepIsNotSaved() = runTest {
        val repository = FakeTallyRepository()
        val viewModel = TallyViewModel(repository)
        advanceUntilIdle()

        viewModel.onAction(TallyAction.ChangeStep(5))
        advanceUntilIdle()

        assertEquals(5, viewModel.state.value.tally.step)
        assertTrue(repository.saved.isEmpty())
    }
}
